style.css:
@-moz-document domain("roblox.com") {
@media (min-width: 1024px) {

    /* Wallpaper */
    html {
      background: url("https://wallpapers.com/images/hd/tokyo-ghoul-flower-oaddrg14a84xb2w9.jpg")
        center center / cover no-repeat fixed !important;
      min-height: 100% !important;
    }

    body {
      background: transparent !important;
      min-height: 100% !important;
    }

    /* Dim overlay */
    html::before {
      content: "";
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.35);
      pointer-events: none;
      z-index: 0;
    }

    /* Keep all content above overlay */
    body, #react-root, #rbx-body {
      position: relative !important;
      z-index: 1 !important;
    }

    /* ----- Make Roblox UI panels transparent ----- */
    /* Main page backgrounds */
    #react-root,
    #rbx-body,
    main,
    .content,
    .container,
    .main-content {
      background: transparent !important;
    }

    /* Common “card/panel” surfaces */
    .section-content,
    .profile-container,
    .profile-header,
    .profile-game,
    .game-details,
    .rbx-tabs-horizontal,
    .rbx-tabs-vertical,
    .tab-content,
    .rbx-divider,
    .card,
    .rbx-card,
    .rbx-panel,
    .rbx-window,
    .rbx-modal,
    .modal-content,
    .dialog-container,
    .stack,
    .MuiPaper-root {
      background: rgba(20,20,20,0.55) !important; /* adjust opacity here */
      backdrop-filter: blur(6px) !important;      /* optional nice glass */
      -webkit-backdrop-filter: blur(6px) !important;
    }

    /* Inputs / textareas can look weird transparent, give them a slightly stronger backing */
    input, textarea, select {
      background: rgba(20,20,20,0.75) !important;
    }
  }
}
